-- PRÉPARATION UNIQUEMENT. NON APPLIQUÉ EN PRODUCTION. Autorisation distincte requise.
-- Aucun GRANT, RLS, changement de table/index/colonne ni modification des dossiers existants.
BEGIN;
-- 01-renouvellement
DO $guard$ BEGIN
