IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner WHERE p.oid='public.exec01_photo_manage(jsonb)'::regprocedure AND md5(pg_get_functiondef(p.oid))='797eadff98c2eca9cf750a29464524c2' AND r.rolname='postgres' AND p.proacl::text='{postgres=X/postgres,service_role=X/postgres}' AND pg_get_function_result(p.oid)='jsonb' AND p.prosecdef=true AND to_jsonb(p.proconfig)='["search_path=public"]'::jsonb AND has_function_privilege('anon',p.oid,'EXECUTE')=false AND has_function_privilege('authenticated',p.oid,'EXECUTE')=false AND has_function_privilege('service_role',p.oid,'EXECUTE')=true) THEN RAISE EXCEPTION 'REFERENCE_OR_RIGHTS_DRIFT_STOP'; END IF;
