IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner WHERE p.oid='public.exec01_dispatch(jsonb)'::regprocedure AND md5(pg_get_functiondef(p.oid))='e9d8b2ad33d864aa7a3ba881e78b82cc' AND r.rolname='postgres' AND p.proacl::text='{postgres=X/postgres,service_role=X/postgres}' AND pg_get_function_result(p.oid)='jsonb' AND p.prosecdef=true AND to_jsonb(p.proconfig)='["search_path=public, extensions"]'::jsonb AND has_function_privilege('anon',p.oid,'EXECUTE')=false AND has_function_privilege('authenticated',p.oid,'EXECUTE')=false AND has_function_privilege('service_role',p.oid,'EXECUTE')=true) THEN RAISE EXCEPTION 'REFERENCE_OR_RIGHTS_DRIFT_STOP'; END IF;
